using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class EventAction : ScriptableObject
{
	[SerializeField]
	private bool enableEvenActionResultTextID;

	[SerializeField]
	[ShowIf("enableEvenActionResultTextID")]
	protected string eventActionButtonTextID;

	[SerializeField]
	private bool ignoreDisableRewardsAnimation;

	[SerializeField]
	[HideIf("hideDontCallOnEventButtonPressed")]
	private bool dontCallOnEventButtonPressed;

	[SerializeField]
	private bool dontDisableShopRewardJoystickInput;

	[SerializeField]
	[HideIf("dontCallOnEventButtonPressed")]
	private bool storeEventsPanelWithDelay;

	[SerializeField]
	[ShowIf("storeEventsPanelWithDelay")]
	private float storeEventsPanelDelay;

	[SerializeField]
	[HideIf("hideDontStoreEventsPanel")]
	private bool dontStoreEventsPanel;

	[SerializeField]
	[HideIf("hideEventButtonPressedUpdateEventDescriptionAndButtons")]
	private bool eventButtonPressedUpdateEventDescriptionAndButtons;

	[SerializeField]
	[ShowIf("eventButtonPressedUpdateEventDescriptionAndButtons")]
	private bool instantlyUpdate = true;

	[SerializeField]
	private bool enableCustomEventButtonOnUpdate;

	[SerializeField]
	[ShowIf("enableCustomEventButtonOnUpdate")]
	protected EventButtonData customEventButtonOnUpdate;

	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private bool enableCustomEventButtonResultText;

	[SerializeField]
	protected bool useResultTextOnLoreTextAndDisableResultText;

	[SerializeField]
	private bool enableCustomEventButtonLoreText;

	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private bool eventActionWithTooltip;

	public bool IgnoreDisableRewardsAnimation => ignoreDisableRewardsAnimation;

	public bool DontCallOnEventButtonPressed => dontCallOnEventButtonPressed;

	public bool DontDisableShopRewardJoystickInput => dontDisableShopRewardJoystickInput;

	private bool hideDontCallOnEventButtonPressed
	{
		get
		{
			if (!eventButtonPressedUpdateEventDescriptionAndButtons)
			{
				return dontStoreEventsPanel;
			}
			return true;
		}
	}

	public float StoreEventsPanelDelay => storeEventsPanelDelay;

	public bool DontStoreEventsPanel => dontStoreEventsPanel;

	private bool hideDontStoreEventsPanel
	{
		get
		{
			if (!dontCallOnEventButtonPressed)
			{
				return eventButtonPressedUpdateEventDescriptionAndButtons;
			}
			return true;
		}
	}

	public bool EventButtonPressedUpdateEventDescriptionAndButtons => eventButtonPressedUpdateEventDescriptionAndButtons;

	private bool hideEventButtonPressedUpdateEventDescriptionAndButtons
	{
		get
		{
			if (!dontCallOnEventButtonPressed)
			{
				return dontStoreEventsPanel;
			}
			return true;
		}
	}

	public bool InstantlyUpdate => instantlyUpdate;

	public bool EnableCustomEventButtonOnUpdate => enableCustomEventButtonOnUpdate;

	public EventButtonData CustomEventButtonOnUpdate => customEventButtonOnUpdate;

	public bool EnableCustomEventButtonResultText => enableCustomEventButtonResultText;

	public bool UseResultTextOnLoreTextAndDisableResultText => useResultTextOnLoreTextAndDisableResultText;

	public bool EnableCustomEventButtonLoreText => enableCustomEventButtonLoreText;

	public bool EventActionWithTooltip => eventActionWithTooltip;

	public virtual void FirstInitialize(EventButton eventButton)
	{
	}

	public virtual void Initialize(EventButton eventButton)
	{
	}

	public virtual void ExecuteAction(EventButton eventButton)
	{
	}

	public virtual string GetEventButtonLoreText(string loreTextID)
	{
		return "";
	}

	public virtual string GetEventButtonResultText(string resultTextID)
	{
		return "";
	}

	public virtual bool IsEventButtonEnabled()
	{
		return true;
	}

	public virtual void InitializeActionDescriptionPanel(ActionDescriptionPanel actionDescriptionPanel)
	{
	}

	protected string GetLocalizedString(string id)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(id);
	}
}
